function PageHeading({eyebrow,title,subtitle,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function Overview({settings,tools,favorites,onPage,onTool,onNotice}){return <><div className="hero-panel"><div className="hero-copy"><div className="eyebrow"><Sparkles size={14}/> YOUR DEVELOPER WORKSPACE</div><h1>Build with curiosity.<br/><span>Ship with confidence.</span></h1><p>A focused space for useful tools, learning experiments, and the next idea worth building.</p><div className="hero-buttons"><button className="primary" onClick={()=>onPage('Developer tools')}>Explore developer tools <ArrowUpRight size={16}/></button><button className="secondary" onClick={()=>onPage('Project lab')}>Explore the lab</button></div><div className="hero-meta"><span><span className="live-dot"/> Local-first workspace</span><span><ShieldAlert size={14}/> Early preview</span></div></div><div className="hero-visual"><div className="orbit orbit-1"/><div className="orbit orbit-2"/><div className="visual-core"><Atom size={47}/></div><div className="float-chip chip-code"><Code2 size={15}/> Build</div><div className="float-chip chip-ai"><WandSparkles size={15}/> Learn</div><div className="float-chip chip-lab"><FlaskConical size={15}/> Experiment</div><div className="visual-caption">IDEAS → PROTOTYPES → PROGRESS</div></div></div><div className="welcome-row"><div><h2>Welcome back, {settings.name||'Developer'} <span className="wave">✦</span></h2><p>Your workspace is ready. Pick a place to start.</p></div><button className="text-action" onClick={()=>onPage('Profile & settings')}>Personalize workspace <ArrowUpRight size={14}/></button></div><div className="stats-grid"><Stat icon={Terminal} label="Browser tools" value={tools.length} detail="Available locally"/><Stat icon={Heart} label="Saved items" value={favorites.length} detail="Your favorites"/><Stat icon={BookOpen} label="Learning mode" value="Ready" detail="Built-in sample content"/><Stat icon={Activity} label="Lab status" value="Preview" detail="Actively evolving"/></div><div className="section-heading"><div><h2>Quick launch</h2><p>Useful starting points for your next session.</p></div><button className="text-action" onClick={()=>onPage('Developer tools')}>All tools <ArrowUpRight size={14}/></button></div><div className="quick-grid">{[{icon:Braces,title:'JSON Formatter',desc:'Validate and format structured data',tool:tools.find(t=>t.kind==='json')},{icon:Code2,title:'Code Playground',desc:'Experiment with HTML, CSS and JS',tool:tools.find(t=>t.kind==='playground')},{icon:GraduationCap,title:'Learning hub',desc:'Vocabulary, summaries and revision',page:'AI & Learning'},{icon:Compass,title:'Developer ecosystem',desc:'Browse official tools and resources',page:'Ecosystem'}].map((x,i)=><button className="quick-card" key={x.title} onClick={()=>x.page?onPage(x.page):onTool(x.tool)}><div className={`quick-icon qi-${i}`}><x.icon size={20}/></div><div><b>{x.title}</b><p>{x.desc}</p></div><ArrowUpRight size={16} className="quick-arrow"/></button>)}</div><div className="bottom-grid"><div className="panel"><div className="panel-title"><div><h3>Lab roadmap</h3><p>What is moving through the pipeline</p></div><span className="subtle-tag">IN PROGRESS</span></div>{[['01','Browser utility suite','Released in this preview','done'],['02','Learning and revision tools','Local demo mode','progress'],['03','Secure AI provider integration','Backend required','planned']].map(a=><div className="roadmap-line" key={a[0]}><div className={`roadmap-num ${a[3]}`}>{a[0]}</div><div><b>{a[1]}</b><span>{a[2]}</span></div><span className={`roadmap-status ${a[3]}`}>{a[3]==='done'?'Available':a[3]==='progress'?'In progress':'Planned'}</span></div>)}</div><div className="panel idea-promo"><div className="promo-symbol"><Lightbulb size={23}/></div><div className="eyebrow">OPEN INNOVATION</div><h3>Have an idea worth testing?</h3><p>Help shape the lab by proposing a small tool, workflow, or learning feature.</p><button className="secondary" onClick={()=>onPage('Submit an idea')}>Submit an idea <ArrowUpRight size={15}/></button><div className="promo-foot">Suggestions are copied locally; no backend is connected.</div></div></div><div className="maintenance"><ShieldAlert size={17}/><div><b>Experimental workspace</b><span>Some learning helpers use simple local logic, not a live AI model. No account or cloud sync is connected.</span></div></div></>}
function Stat({icon:Icon,label,value,detail}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><Icon size={17}/></div><strong>{value}</strong><small>{detail}</small></div>}
function ToolsPage({tools,query,setQuery,category,setCategory,activeTool,setActiveTool,favorites,toggleFav,toast}){const cats=['All',...new Set(tools.map(t=>t.category))];const filtered=tools.filter(t=>(category==='All'||t.category===category)&&(t.name+' '+t.desc+' '+t.category).toLowerCase().includes(query.toLowerCase()));return <><PageHeading eyebrow="DEVELOPER WORKSPACE" title="Developer tools" subtitle="Small, focused utilities that run in your browser. Your input stays on this device unless you choose to copy it elsewhere." action={<span className="subtle-tag">{tools.length} TOOLS</span>}/><div className="search-bar"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search tools by name or capability…" aria-label="Search developer tools"/><kbd>CTRL K</kbd></div><div className="filter-row">{cats.map(c=><button key={c} className={`filter-chip ${category===c?'selected':''}`} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="tools-layout"><div className="tool-list"><div className="list-heading"><span>{filtered.length} tools found</span><span>Choose a tool to open it</span></div>{filtered.map(t=><div role="button" tabIndex={0} key={t.kind} className={`tool-list-item ${activeTool.kind===t.kind?'chosen':''}`} onClick={()=>setActiveTool(t)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setActiveTool(t)}}}><div className="tool-item-icon"><Code2 size={18}/></div><div className="tool-item-copy"><b>{t.name}</b><span>{t.desc}</span><small>{t.category}</small></div><button className={`favorite-mini ${favorites.includes('tool:'+t.kind)?'favorited':''}`} aria-label="Save tool" onClick={e=>{e.stopPropagation();toggleFav('tool:'+t.kind);toast(favorites.includes('tool:'+t.kind)?'Removed from saved tools':'Saved to favorites')}}><Heart size={16} fill={favorites.includes('tool:'+t.kind)?'currentColor':'none'}/></button></div>)}{!filtered.length&&<div className="empty-state"><Search size={24}/><b>No matching tools</b><span>Try a different search or category.</span><button className="secondary" onClick={()=>{setQuery('');setCategory('All')}}>Clear filters</button></div>}</div><div className="tool-workspace"><div className="tool-workspace-head"><div className="tool-item-icon large"><Terminal size={20}/></div><div><div className="eyebrow">{activeTool.category}</div><h2>{activeTool.name}</h2><p>{activeTool.desc}</p></div><button className={`icon-button save-tool ${favorites.includes('tool:'+activeTool.kind)?'saved':''}`} onClick={()=>toggleFav('tool:'+activeTool.kind)} aria-label="Save current tool"><Heart size={18} fill={favorites.includes('tool:'+activeTool.kind)?'currentColor':'none'}/></button></div><ToolRunner key={activeTool.kind} tool={activeTool} toast={toast}/></div></div></>}
function ToolRunner({tool,toast}){const [input,setInput]=useState(tool.kind==='playground'?'<h1>Hello, lab.</h1>\n<p>Edit this markup, then preview it.</p>':'');const [second,setSecond]=useState('');const [output,setOutput]=useState('');const [error,setError]=useState('');const [extra,setExtra]=useState('');const [color,setColor]=useState('#6d5dfc');const [file,setFile]=useState(null);const [imageResult,setImageResult]=useState('');const [dimensions,setDimensions]=useState({width:800,height:600});const [mode,setMode]=useState('encode');const [length,setLength]=useState(18);const [regexFlags,setRegexFlags]=useState('g');const [regexPattern,setRegexPattern]=useState('\b\w{4}\b');const [regexText,setRegexText]=useState('Build useful tools, learn every day.');const [gradient,setGradient]=useState(135);const [gradient2,setGradient2]=useState('#16c7df');
 const run=async()=>{setError('');setOutput('');try{let result='';switch(tool.kind){case'json':result=formatJson(input);break;case'xml':{const parser=new DOMParser(),doc=parser.parseFromString(input,'application/xml');if(doc.querySelector('parsererror'))throw Error('Invalid XML. Check tag names and nesting.');result=input.replace(/>\s*</g,'>\n<').split('\n').map((line,i)=>`${'  '.repeat(Math.max(0,(line.match(/^<[^/!?][^>]*[^/]>/)?1:0)-(line.match(/^<\//)?1:0)))}${line}`).join('\n');break}case'markdown':result=input.replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>').replace(/`(.*?)`/g,'<code>$1</code>').replace(/\n/g,'<br>');break;case'regex':{const re=new RegExp(regexPattern,regexFlags);result=JSON.stringify({matches:regexText.match(re)||[],count:(regexText.match(re)||[]).length},null,2);break}case'gradient':result=`background: linear-gradient(${gradient}deg, ${color}, ${gradient2});`;break;case'color':{const rgb=hexToRgb(color);result=JSON.stringify({hex:color,rgb,contrastOnWhite:contrast(rgb,[255,255,255]).toFixed(2)+':1',contrastOnBlack:contrast(rgb,[0,0,0]).toFixed(2)+':1'},null,2);break}case'htmlentity':result=mode==='encode'?input.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'):input.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&');break;case'url':result=mode==='encode'?encodeURIComponent(input):decodeURIComponent(input);break;case'base64':result=mode==='encode'?encodeBase64(input):decodeBase64(input);break;case'uuid':result=Array.from({length:Math.max(1,Math.min(20,Number(length)||1))},makeUuid).join('\n');break;case'timestamp':{const n=Number(input);if(!input.trim())throw Error('Enter a Unix timestamp or date string.');const d=Number.isFinite(n)?new Date(Math.abs(n)<1e12?n*1000:n):new Date(input);if(Number.isNaN(d.getTime()))throw Error('Could not parse that timestamp or date.');result=`ISO: ${d.toISOString()}\nLocal: ${d.toLocaleString()}\nUnix seconds: ${Math.floor(d.getTime()/1000)}`;break}case'base':{const n=parseInt(input.trim(),Number(extra||10));if(Number.isNaN(n))throw Error('Enter an integer for the selected input base.');result=`Binary: ${n.toString(2)}\nOctal: ${n.toString(8)}\nDecimal: ${n.toString(10)}\nHexadecimal: ${n.toString(16).toUpperCase()}`;break}case'diff':{const d=textDiff(input,second);result=[...d.removed.map(x=>'- '+x),...d.added.map(x=>'+ '+x),...d.same.map(x=>'  '+x)].join('\n')||'No differences';break}case'jwt':{const parts=input.split('.');if(parts.length<2)throw Error('Paste a JWT with at least header and payload segments.');result='Header:\n'+JSON.stringify(JSON.parse(decodeBase64(parts[0].replace(/-/g,'+').replace(/_/g,'/'))),null,2)+'\nPayload:\n'+JSON.stringify(JSON.parse(decodeBase64(parts[1].replace(/-/g,'+').replace(/_/g,'/'))),null,2)+'\n\nNote: signature not verified.';break}case'hash':{const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(input));result=Array.from(new Uint8Array(bytes)).map(b=>b.toString(16).padStart(2,'0')).join('');break}case'password':{const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*_-+=';const bytes=crypto.getRandomValues(new Uint8Array(Math.max(8,Math.min(128,Number(length)||18))));result=Array.from(bytes,b=>alphabet[b%alphabet.length]).join('');break}case'csv':result=JSON.stringify(csvToJson(input),null,2);break;case'jsoncsv':{const arr=JSON.parse(input);if(!Array.isArray(arr)||!arr.length||typeof arr[0]!=='object')throw Error('Provide a non-empty JSON array of objects.');const keys=[...new Set(arr.flatMap(o=>Object.keys(o)))];result=[keys.join(','),...arr.map(o=>keys.map(k=>JSON.stringify(o[k]??'')).join(','))].join('\n');break}case'counter':result=JSON.stringify(countText(input),null,2);break;case'case':result=extra==='upper'?input.toUpperCase():extra==='lower'?input.toLowerCase():extra==='title'?input.toLowerCase().replace(/\b\w/g,c=>c.toUpperCase()):extra==='sentence'?input.toLowerCase().replace(/(^\s*\w|[.!?]\s+\w)/g,c=>c.toUpperCase()):input.toLowerCase().replace(/[^\w]+(.)/g,(_,c)=>c.toUpperCase());break;case'clean':result=input.split(/\r?\n/).map(x=>x.trim().replace(/\s+/g,' ')).filter(Boolean).join('\n');break;case'duplicates':result=[...new Set(input.split(/\r?\n/))].join('\n');break;case'replace':if(!extra)throw Error('Enter the phrase to find in the second field.');result=input.split(extra).join(second);break;case'lorem':result=Array.from({length:Math.max(1,Math.min(12,Number(length)||3))},(_,i)=>['Lorem ipsum dolor sit amet, consectetur adipiscing elit.','Integer posuere erat a ante venenatis dapibus posuere velit aliquet.','Donec sed odio dui. Cras mattis consectetur purus sit amet fermentum.'][i%3]).join('\n\n');break;case'sample':result=JSON.stringify(Array.from({length:Math.max(1,Math.min(25,Number(length)||5))},(_,i)=>({id:i+1,name:['Ari','Sam','Jordan','Taylor','Morgan'][i%5],active:i%2===0,score:Math.floor(Math.random()*100)})),null,2);break;default:result='This tool is available in the workspace.'}setOutput(result)}catch(e){setError(e.message||'Could not process input. Check the values and try again.')}};
 const copy=async(text)=>{try{await navigator.clipboard.writeText(text);toast('Copied to clipboard')}catch{toast('Clipboard access unavailable; select and copy the output manually')}};
 if(tool.kind==='playground')return <div className="runner"><div className="playground-fields"><label>HTML<textarea value={input} onChange={e=>setInput(e.target.value)} className="mono-input" rows="6"/></label><label>CSS<textarea value={second} onChange={e=>setSecond(e.target.value)} placeholder="body { font-family: sans-serif; padding: 2rem; }" rows="5"/></label><label>JavaScript<textarea value={extra} onChange={e=>setExtra(e.target.value)} placeholder="document.querySelector('h1')?.classList.add('hello');" rows="4"/></label></div><div className="runner-actions"><button className="primary" onClick={()=>setOutput('preview')}>Update preview <ArrowUpRight size={15}/></button><button className="secondary" onClick={()=>{setInput('<h1>Hello, lab.</h1>\n<p>Edit this markup, then preview it.</p>');setSecond('');setExtra('');setOutput('')}}>Reset</button></div><div className="output-panel"><div className="output-head"><span>LIVE PREVIEW · SANDBOXED IFRAME</span></div><iframe title="Code playground preview" sandbox="allow-scripts" referrerPolicy="no-referrer" srcDoc={`<!doctype html><html><head><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; img-src data:;"><style>body{font-family:system-ui;padding:1.25rem;color:#151827}${second}</style></head><body>${input}<script>${extra.replace(/<\/script/gi,'<\\/script')}</script></body></html>`}/></div><p className="field-hint">The preview runs in a sandboxed iframe. Do not paste code from untrusted sources.</p></div>;
 if(tool.kind==='image')return <div className="runner"><label>Choose an image<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{setFile(e.target.files?.[0]||null);setImageResult('');setError('')}}/></label><div className="settings-two"><label>Maximum width (px)<input type="number" min="1" max="6000" value={dimensions.width} onChange={e=>setDimensions(d=>({...d,width:+e.target.value}))}/></label><label>Maximum height (px)<input type="number" min="1" max="6000" value={dimensions.height} onChange={e=>setDimensions(d=>({...d,height:+e.target.value}))}/></label></div><label>Output format<select value={mode} onChange={e=>setMode(e.target.value)}><option value="image/jpeg">JPEG</option><option value="image/webp">WebP</option><option value="image/png">PNG</option></select></label><button className="primary" onClick={()=>{if(!file){setError('Choose an image file first.');return}if(file.size>15*1024*1024){setError('Choose an image smaller than 15 MB.');return}const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const scale=Math.min(1,Math.max(1,dimensions.width)/img.width,Math.max(1,dimensions.height)/img.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{URL.revokeObjectURL(url);if(!blob){setError('The browser could not export this image format.');return}const resultUrl=URL.createObjectURL(blob);setImageResult(resultUrl);setOutput(`Original: ${img.width} × ${img.height} px\nOutput: ${canvas.width} × ${canvas.height} px\nFile size: ${(blob.size/1024).toFixed(1)} KB`);setError('')},mode,.88)};img.onerror=()=>{URL.revokeObjectURL(url);setError('Could not read this image. Try PNG, JPEG or WebP.')} ;img.src=url}}>Resize / compress locally <ArrowUpRight size={15}/></button>{error&&<p className="error">{error}</p>}{output&&<Output value={output} />}{imageResult&&<div className="output-panel"><div className="output-head"><span>PROCESSED IMAGE</span><a href={imageResult} download={`ni-lab-image.${mode==='image/jpeg'?'jpg':mode==='image/webp'?'webp':'png'}`}>Download image <ArrowUpRight size={13}/></a></div><img src={imageResult} alt="Resized output" style={{display:'block',maxWidth:'100%',maxHeight:320,margin:'12px auto',objectFit:'contain'}}/></div>}<p className="field-hint">Processing happens in this browser. Max input size: 15 MB. Animated images and unsupported formats are not preserved.</p></div>;
 if(tool.kind==='gradient')return <div className="runner"><div className="gradient-preview" style={{background:`linear-gradient(${gradient}deg,${color},${gradient2})`}}/><label>Direction <input type="range" min="0" max="360" value={gradient} onChange={e=>setGradient(+e.target.value)}/><span className="range-value">{gradient}°</span></label><div className="color-pair"><label>Start color<input type="color" value={color} onChange={e=>setColor(e.target.value)}/></label><label>End color<input type="color" value={gradient2} onChange={e=>setGradient2(e.target.value)}/></label></div><button className="primary" onClick={()=>copy(`background: linear-gradient(${gradient}deg, ${color}, ${gradient2});`)}><Copy size={15}/> Copy CSS</button><Output value={`background: linear-gradient(${gradient}deg, ${color}, ${gradient2});`}/></div>;
 if(tool.kind==='color')return <div className="runner"><label>Choose a color<input type="color" value={color} onChange={e=>setColor(e.target.value)} className="big-color"/></label><button className="primary" onClick={run}>Check color contrast</button><Output value={output}/>{error&&<p className="error">{error}</p>}</div>;
 if(tool.kind==='regex')return <div className="runner"><label>Regular expression<input value={regexPattern} onChange={e=>setRegexPattern(e.target.value)} className="mono-input"/></label><label>Flags<input value={regexFlags} onChange={e=>setRegexFlags(e.target.value)} placeholder="g i m"/></label><label>Test text<textarea value={regexText} onChange={e=>setRegexText(e.target.value)} rows="5"/></label><button className="primary" onClick={run}>Test expression</button><Output value={output}/>{error&&<p className="error">{error}</p>}</div>;
 if(tool.kind==='base')return <div className="runner"><label>Integer<input value={input} onChange={e=>setInput(e.target.value)} placeholder="e.g. 255"/></label><label>Input base<select value={extra||'10'} onChange={e=>setExtra(e.target.value)}><option value="2">Binary (2)</option><option value="8">Octal (8)</option><option value="10">Decimal (10)</option><option value="16">Hexadecimal (16)</option></select></label><button className="primary" onClick={run}>Convert number</button><Output value={output}/>{error&&<p className="error">{error}</p>}</div>;
 if(tool.kind==='uuid'||tool.kind==='password'||tool.kind==='lorem'||tool.kind==='sample')return <div className="runner"><label>{tool.kind==='uuid'?'Number of IDs':tool.kind==='password'?'Password length':tool.kind==='lorem'?'Paragraphs':'Number of records'}<input type="number" min="1" max={tool.kind==='password'?128:25} value={length} onChange={e=>setLength(+e.target.value)}/></label><button className="primary" onClick={run}>{tool.kind==='uuid'?'Generate UUIDs':tool.kind==='password'?'Generate password':tool.kind==='lorem'?'Generate text':'Generate sample data'} <Sparkles size={15}/></button><Output value={output}/>{error&&<p className="error">{error}</p>}</div>;
 if(tool.kind==='timestamp')return <div className="runner"><label>Unix timestamp or date string<input value={input} onChange={e=>setInput(e.target.value)} placeholder="e.g. 1792867200 or 2026-10-24"/></label><button className="primary" onClick={run}>Convert timestamp</button><Output value={output}/>{error&&<p className="error">{error}</p>}</div>;
 if(tool.kind==='htmlentity'||tool.kind==='url'||tool.kind==='base64')return <div className="runner"><div className="segmented"><button className={mode==='encode'?'active':''} onClick={()=>setMode('encode')}>Encode</button><button className={mode==='decode'?'active':''} onClick={()=>setMode('decode')}>Decode</button></div><label>Input<textarea value={input} onChange={e=>setInput(e.target.value)} rows="7" placeholder="Enter text here…"/></label><button className="primary" onClick={run}>{mode==='encode'?'Encode':'Decode'} <ArrowUpRight size={15}/></button><Output value={output}/>{error&&<p className="error">{error}</p>}</div>;
 return <div className="runner"><label>{tool.kind==='diff'?'Original text':tool.kind==='replace'?'Text to edit':tool.kind==='jwt'?'JWT token':tool.kind==='csv'?'CSV input':tool.kind==='jsoncsv'?'JSON array':tool.kind==='hash'?'Text to hash':tool.kind==='xml'?'XML input':tool.kind==='markdown'?'Markdown source':'Input'}<textarea value={input} onChange={e=>setInput(e.target.value)} rows="7" placeholder={tool.kind==='json'?'Paste JSON, e.g. {"hello":"world"}':tool.kind==='csv'?'name,age\nAda,20':'Enter or paste your text here…'} /></label>{['diff','replace'].includes(tool.kind)&&<label>{tool.kind==='diff'?'Compare with':'Replace with'}<textarea value={second} onChange={e=>setSecond(e.target.value)} rows="5" placeholder={tool.kind==='diff'?'Second version…':'Replacement text…'}/></label>}{tool.kind==='replace'&&<label>Find phrase<input value={extra} onChange={e=>setExtra(e.target.value)} placeholder="Exact phrase to find"/></label>}{tool.kind==='case'&&<label>Conversion<select value={extra||'camel'} onChange={e=>setExtra(e.target.value)}><option value="upper">UPPERCASE</option><option value="lower">lowercase</option><option value="title">Title Case</option><option value="sentence">Sentence case</option><option value="camel">camelCase</option></select></label>}{tool.kind==='lorem'&&<label>Paragraphs<input type="number" value={length} min="1" max="12" onChange={e=>setLength(+e.target.value)}/></label>}<div className="runner-actions"><button className="primary" onClick={run}>Run tool <ArrowUpRight size={15}/></button><button className="secondary" onClick={()=>{setInput('');setSecond('');setOutput('');setError('')}}>Reset</button>{output&&<button className="secondary" onClick={()=>copy(output)}><Copy size={15}/> Copy output</button>}</div>{error&&<p className="error" role="alert">{error}</p>}<Output value={output}/>{['jwt','hash','password'].includes(tool.kind)&&<p className="field-hint">{tool.kind==='jwt'?'JWT decoding only displays data. It does not verify a signature or establish trust.':tool.kind==='hash'?'Hashing is performed locally with Web Crypto.':'Use a password manager for important credentials; generated text is not saved by this tool.'}</p>}</div>
}
function Output({value}){if(!value)return null;return <div className="output-panel"><div className="output-head"><span>OUTPUT</span><span className="output-ready"><span className="live-dot"/> Ready</span></div><pre>{value}</pre></div>}
function hexToRgb(hex){const h=hex.replace('#','');return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)]}
function luminance(rgb){const a=rgb.map(v=>{v/=255;return v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4)});return .2126*a[0]+.7152*a[1]+.0722*a[2]}
function contrast(a,b){const x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function Learning({toast}){const [level,setLevel]=useState('All');const [wordIndex,setWordIndex]=useState(0);const [saved,setSaved]=useState(()=>readStore('ni-vocabulary',[]));const [text,setText]=useState('');const [summary,setSummary]=useState('');const [summaryLength,setSummaryLength]=useState('medium');const [notes,setNotes]=useState('');const [qtype,setQtype]=useState('Short answer');const [questions,setQuestions]=useState('');const [flashIndex,setFlashIndex]=useState(0);const [flipped,setFlipped]=useState(false);const shownWords=words.filter(w=>level==='All'||w.level===level);const word=shownWords[wordIndex%shownWords.length]||words[0];useEffect(()=>localStorage.setItem('ni-vocabulary',JSON.stringify(saved)),[saved]);const makeQuestions=()=>{const lines=notes.split(/[.!?\n]+/).map(x=>x.trim()).filter(x=>x.length>12);if(!lines.length){setQuestions('Add study notes with at least one meaningful sentence first.');return}setQuestions(lines.slice(0,8).map((s,i)=>`${i+1}. ${qtype==='Multiple choice'?'Which statement is described by this note?':qtype==='Descriptive'?'Explain the following idea in your own words:':'What does this note say about'} “${s}”?`).join('\n\n')+'\n\nNote: These are prompts based only on your text. Verify answers against your source material.')};return <><PageHeading eyebrow="LEARNING STUDIO" title="Learn a little every day" subtitle="Lightweight study helpers for practice and revision. These are local demo tools, not a connected large language model."/><div className="learning-grid"><section className="learning-card vocab-card"><div className="card-icon purple"><BookOpen size={19}/></div><div className="eyebrow">WORD OF THE MOMENT</div><div className="vocab-toolbar"><span className="subtle-tag">{word.level}</span><select value={level} onChange={e=>{setLevel(e.target.value);setWordIndex(0)}}><option>All</option><option>Beginner</option><option>Intermediate</option><option>Academic</option><option>Advanced</option></select></div><h2>{word.word}</h2><p>{word.meaning}</p><div className="example-box"><small>IN A SENTENCE</small><p>{word.sentence}</p></div><p className="synonyms"><span>Synonyms</span> {word.synonyms}</p><div className="card-actions"><button className="primary" onClick={()=>setWordIndex(i=>i+1)}>Next word <ArrowUpRight size={15}/></button><button className="secondary" onClick={()=>{setSaved(s=>s.includes(word.word)?s:[...s,word.word]);toast('Word saved to your local vocabulary')}}><Heart size={15}/> Save word</button></div><div className="saved-words"><b>Saved vocabulary</b><span>{saved.length?saved.join(' · '):'No saved words yet'}</span></div></section><section className="learning-card"><div className="card-icon cyan"><Sparkles size={19}/></div><div className="eyebrow">TEXT SUMMARIZER</div><h2>Find the main ideas</h2><p className="card-description">A simple extractive heuristic. It does not understand context like a language model would.</p><textarea value={text} onChange={e=>setText(e.target.value)} rows="6" placeholder="Paste study notes or an article excerpt…"/><div className="inline-controls"><label>Length<select value={summaryLength} onChange={e=>setSummaryLength(e.target.value)}><option value="short">Short</option><option value="medium">Medium</option><option value="detailed">Detailed</option></select></label><button className="primary" onClick={()=>setSummary(text.trim()?summarize(text,summaryLength):'Please add text to summarize.')}>Summarize</button></div>{summary&&<div className="result-box"><div className="result-title">SUMMARY <button className="icon-button" onClick={()=>navigator.clipboard?.writeText(summary).then(()=>toast('Summary copied')).catch(()=>toast('Select and copy the summary'))} aria-label="Copy summary"><Copy size={14}/></button></div><p>{summary}</p></div>}</section><section className="learning-card"><div className="card-icon blue"><GraduationCap size={19}/></div><div className="eyebrow">STUDY QUESTION GENERATOR</div><h2>Turn notes into prompts</h2><p className="card-description">Questions are formed from sentences you provide. No outside facts or unsupported answer key is added.</p><textarea value={notes} onChange={e=>setNotes(e.target.value)} rows="5" placeholder="Paste a paragraph or your class notes…"/><div className="inline-controls"><label>Question type<select value={qtype} onChange={e=>setQtype(e.target.value)}><option>Short answer</option><option>Multiple choice</option><option>Descriptive</option></select></label><button className="primary" onClick={makeQuestions}>Generate prompts</button></div>{questions&&<div className="result-box"><div className="result-title">REVISION PROMPTS</div><pre>{questions}</pre><button className="text-action" onClick={()=>navigator.clipboard?.writeText(questions).then(()=>toast('Questions copied')).catch(()=>toast('Select and copy questions'))}>Copy questions <Copy size={14}/></button></div>}</section><section className="learning-card flashcard-card"><div className="card-icon pink"><Atom size={19}/></div><div className="eyebrow">QUICK FLASHCARDS</div><h2>Recall before you review</h2><p className="card-description">Tap the card to reveal the answer, then move to the next prompt.</p><button className="flashcard" onClick={()=>setFlipped(v=>!v)}><span>{flipped?'ANSWER':'QUESTION'}</span><b>{flipped?['A reusable set of instructions that performs a task.','A named storage location for a value.','A way to track changes to source files.'][flashIndex%3]:['What is a function?','What is a variable?','What is version control?'][flashIndex%3]}</b><small>Click to {flipped?'show question':'reveal answer'}</small></button><button className="secondary" onClick={()=>{setFlashIndex(i=>i+1);setFlipped(false)}}>Next flashcard <ArrowUpRight size={15}/></button></section></div><div className="maintenance"><Bot size={17}/><div><b>About AI in this preview</b><span>No model provider is configured. Summaries and questions are generated locally with basic heuristics; connect a secured backend to enable a real AI model.</span></div></div></>}
function Ecosystem({query,setQuery,favorites,toggleFav}){const [cat,setCat]=useState('All');const categories=['All',...new Set(resources.map(r=>r.category))];const list=resources.filter(r=>(cat==='All'||r.category===cat)&&(r.name+' '+r.category+' '+r.description).toLowerCase().includes(query.toLowerCase()));return <><PageHeading eyebrow="DEVELOPER ECOSYSTEM" title="Good tools, one launchpad" subtitle="A curated directory of official developer resources. These links open third-party websites; no partnership or integration is implied." action={<span className="subtle-tag">{resources.length} RESOURCES</span>}/><div className="search-bar"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search products, categories, capabilities…"/><kbd>SEARCH</kbd></div><div className="filter-row">{categories.map(c=><button className={`filter-chip ${cat===c?'selected':''}`} key={c} onClick={()=>setCat(c)}>{c}</button>)}</div><div className="resource-grid">{list.map(r=><article className="resource-card" key={r.name}><div className="resource-top"><div className="resource-monogram">{r.name.split(/\s/).map(x=>x[0]).join('').slice(0,2)}</div><button className={`favorite-mini ${favorites.includes('resource:'+r.name)?'favorited':''}`} onClick={()=>toggleFav('resource:'+r.name)} aria-label={`Save ${r.name}`}><Heart size={16} fill={favorites.includes('resource:'+r.name)?'currentColor':'none'}/></button></div><span className="resource-category">{r.category}</span><h3>{r.name}</h3><p>{r.description}</p><a href={r.url} target="_blank" rel="noreferrer">Official website <ExternalLink size={14}/></a></article>)}</div>{!list.length&&<div className="empty-state"><Search size={24}/><b>No resources found</b><span>Try a different keyword.</span></div>}</>}
function Projects({onIdea}){const projects=[['Developer Utility Suite','Released','Useful browser-side tools for everyday formatting and conversion.','released'],['Learning Studio','In Development','Vocabulary, flashcards, summarization heuristics and revision prompts.','progress'],['Secure AI Gateway','Planned','Provider abstraction, server-side key storage, validation and request limits.','planned'],['Cloud Profiles & Sync','Planned','Optional accounts and server-backed preferences with access controls.','planned'],['Maintainer Console','Idea','Review submissions and manage project notes with real authorization.','idea']];return <><PageHeading eyebrow="EXPERIMENTAL PROJECTS" title="The project laboratory" subtitle="A transparent view of experiments and planned work. Statuses describe this starter build, not a promise of delivery." action={<button className="primary" onClick={onIdea}>Suggest a feature <Lightbulb size={15}/></button>}/><div className="roadmap-banner"><div className="roadmap-banner-icon"><FlaskConical size={24}/></div><div><div className="eyebrow">CURRENT RELEASE · v0.1.0</div><h2>Start small. Keep it useful.</h2><p>The initial workspace focuses on client-side utilities, learning demos and a directory. Cloud accounts, production AI and payment flows are not enabled.</p></div></div><div className="project-grid">{projects.map(([name,status,desc,kind],i)=><article className="project-card" key={name}><div className="project-top"><span className="project-id">LAB-{String(i+1).padStart(3,'0')}</span><span className={`project-status ${kind}`}>{status}</span></div><div className="project-symbol"><FolderKanban size={20}/></div><h3>{name}</h3><p>{desc}</p><div className="project-bottom"><span>{kind==='released'?'Available now':kind==='progress'?'Partial implementation':'Not implemented'}</span><span>↗</span></div></article>)}</div><section className="panel release-panel"><div className="panel-title"><div><h3>Release notes</h3><p>Version history for this starter project</p></div></div><div className="release-item"><span className="release-dot"/><div><b>v0.1.0 — Initial preview</b><p>Access gate, local settings, browser utilities, learning demos, ecosystem directory, roadmap and idea-copy workflow.</p><small>2026 · Experimental</small></div></div><div className="release-item"><span className="release-dot muted-dot"/><div><b>v0.2.0 — Planned</b><p>Automated browser tests, server-side AI gateway, and optional authenticated persistence.</p><small>Not scheduled</small></div></div></section></>}
function IdeaPage({idea,setIdea,toast}){const [error,setError]=useState('');const submit=e=>{e.preventDefault();if(!idea.title.trim()||!idea.description.trim()){setError('Add an idea title and description before continuing.');return}setError('');const body=`NI Software Labs idea submission\n\nTitle: ${idea.title}\nCategory: ${idea.category}\nName: ${idea.name||'Not provided'}\nEmail: ${idea.email||'Not provided'}\nProject link: ${idea.link||'Not provided'}\n\nDescription:\n${idea.description}`;setIdea({...idea});navigator.clipboard?.writeText(body).then(()=>toast('Idea copied. No server submission was made.')).catch(()=>toast('Idea is ready below to copy manually.'));};const fields=[['name','Your name (optional)','text'],['email','Email (optional)','email'],['title','Idea title *','text'],['link','Project link (optional)','url']];return <><PageHeading eyebrow="OPEN INNOVATION" title="Suggest something useful" subtitle="Have an idea for a tool, workflow or learning feature? Draft it here. This demo does not send or store submissions on a server."/><div className="idea-layout"><form className="idea-form panel" onSubmit={submit}><div className="form-grid">{fields.map(([key,label,type])=><label key={key}>{label}<input type={type} value={idea[key]} onChange={e=>setIdea(s=>({...s,[key]:e.target.value}))} placeholder={key==='title'?'e.g. API response visualizer':key==='link'?'https://…':''} required={key==='title'}/></label>)}<label>Category<select value={idea.category} onChange={e=>setIdea(s=>({...s,category:e.target.value}))}>{['Tool idea','Learning feature','Developer experience','Security','Project improvement','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label className="wide-field">Description *<textarea value={idea.description} onChange={e=>setIdea(s=>({...s,description:e.target.value}))} rows="6" placeholder="What problem does this solve? Who would use it? What would a useful first version do?" required/></label></div>{error&&<p className="error">{error}</p>}<div className="form-foot"><span><ShieldAlert size={15}/> Demo mode: nothing is sent to a server.</span><button className="primary" type="submit">Prepare submission <ArrowUpRight size={15}/></button></div><div className="idea-preview"><b>Submission preview</b><pre>{idea.title?`${idea.title}\n${idea.category}\n\n${idea.description||'Add a description above.'}`:'Your idea will appear here as you type.'}</pre><button type="button" className="text-action" onClick={()=>navigator.clipboard?.writeText(JSON.stringify(idea,null,2)).then(()=>toast('Idea JSON copied')).catch(()=>toast('Clipboard unavailable'))}>Copy idea data <Copy size={14}/></button></div></form><aside className="idea-aside"><div className="promo-symbol"><Lightbulb size={23}/></div><h3>Help make the lab better</h3><p>The best early features solve one real problem cleanly. Keep your proposal focused and testable.</p><div className="tip"><span>01</span><div><b>Describe the problem</b><p>What takes too long or feels harder than it should?</p></div></div><div className="tip"><span>02</span><div><b>Suggest the smallest version</b><p>What is the first useful behavior?</p></div></div><div className="tip"><span>03</span><div><b>Be clear about data</b><p>Does it need a server, account, or API key?</p></div></div></aside></div></>}
function SettingsPage({settings,setSettings,favorites,onLock,toast}){const update=(k,v)=>setSettings(s=>({...s,[k]:v}));return <><PageHeading eyebrow="YOUR WORKSPACE" title="Profile & settings" subtitle="These preferences are stored in this browser only. They are not synced to an account or server." action={<button className="secondary" onClick={onLock}><LogOut size={15}/> Lock workspace</button>}/><div className="settings-layout"><section className="panel settings-main"><div className="settings-section-title"><div className="avatar big-avatar">{(settings.name||'D').slice(0,1).toUpperCase()}</div><div><h2>Developer profile</h2><p>Personalize your local workspace.</p></div></div><label>Display name<input value={settings.name} onChange={e=>update('name',e.target.value)} placeholder="Developer" maxLength="40"/></label><div className="settings-two"><label>Developer level<select value={settings.level} onChange={e=>update('level',e.target.value)}>{['Beginner','Intermediate','Advanced','Student'].map(x=><option key={x}>{x}</option>)}</select></label><label>Preferred language<select value={settings.language} onChange={e=>update('language',e.target.value)}>{['JavaScript','TypeScript','Python','Java','C','C++','HTML/CSS'].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="divider-line"/><div className="settings-section-title"><div><h2>Appearance</h2><p>Adjust how the workspace looks and feels.</p></div></div><label>Theme<select value={settings.theme} onChange={e=>update('theme',e.target.value)}><option value="dark">Dark — midnight violet</option><option value="light">Light — soft neutral</option></select></label><div className="setting-row"><div><b>Reduced motion</b><p>Reduce decorative movement and transitions.</p></div><button className={`toggle ${settings.motion?'on':''}`} onClick={()=>update('motion',!settings.motion)} role="switch" aria-checked={settings.motion} aria-label="Reduced motion"><span/></button></div><div className="setting-row"><div><b>Compact tool cards</b><p>Use denser spacing in tool lists.</p></div><button className={`toggle ${settings.layout==='compact'?'on':''}`} onClick={()=>update('layout',settings.layout==='compact'?'comfortable':'compact')} role="switch" aria-checked={settings.layout==='compact'} aria-label="Compact tool cards"><span/></button></div><div className="divider-line"/><div className="settings-section-title"><div><h2>Local data</h2><p>Saved preferences, favorites and vocabulary remain in this browser's local storage.</p></div></div><div className="local-data-row"><div><b>Saved items</b><span>{favorites.length} favorite tools and resources</span></div><button className="secondary" onClick={()=>{localStorage.removeItem('ni-favorites');localStorage.removeItem('ni-vocabulary');toast('Saved favorites and vocabulary cleared')}}>Clear saved items</button></div><div className="local-data-row"><div><b>Privacy</b><span>No account, backend or analytics is configured in this starter.</span></div><button className="secondary" onClick={()=>toast('This demo stores preferences in localStorage and access in sessionStorage.')}>Data details</button></div><div className="settings-foot"><Check size={15}/> Changes save automatically on this device.</div></section><aside className="settings-aside"><div className="settings-aside-top"><ShieldAlert size={20}/><b>Preview security note</b></div><p>The access code gate is only a demo. Frontend code is public after deployment, so it cannot protect private content or APIs.</p><p>Use server-side authentication or an identity-aware access layer before publishing sensitive functionality.</p><div className="settings-aside-top"><LockKeyhole size={20}/><b>Session controls</b></div><p>Locking ends this browser tab's preview session. Local preferences remain saved unless you clear them.</p><button className="secondary full" onClick={onLock}><LogOut size={15}/> Lock workspace now</button></aside></div></>}
